import numpy as np

def check_equation(a, b, c):
    """Checks if a^2*b^2 = 2(a + b - c)(b + c - a)(c + a - b) holds."""
    if a <= 0 or b <= 0 or c <= 0:
        return False
    # Triangle inequality check (positive area implies strict inequality)
    if a + b <= c or b + c <= a or c + a <= b:
        return False

    lhs = a**2 * b**2
    rhs = 2 * (a + b - c) * (b + c - a) * (c + a - b)

    # Use a small tolerance for floating point comparison
    return np.isclose(lhs, rhs)

# --- Case 1: Equilateral Triangle (a=b=c) ---
L = 2.0
if check_equation(L, L, L):
    print(f"Solution (2, 2, 2). Perimeter: 6.0")

# --- Case 2: Isosceles Triangle (a=b) ---
solutions_isosceles = []
# Increased the range for 'a' up to 15.0
A_range = np.arange(1, 15.1, 0.25) 

for a in A_range:
    # f(c) = 2*c^3 - 4*a*c^2 + a^4 = 0
    def f(c):
        return 2 * c**3 - 4 * a * c**2 + a**4

    # Search c in (0, 2a) with finer steps
    C_steps = np.linspace(0, 2*a, 50)

    for c in C_steps:
        # Check if f(c) is close to zero, indicating a potential root
        if np.isclose(f(c), 0):
            # Verify with the original equation check for robustness
            if check_equation(a, a, c):
                perimeter = 2 * a + c
                # Store unique solutions based on a
                if not any(np.isclose(s[0], a) for s in solutions_isosceles):
                    solutions_isosceles.append((a, a, c, perimeter))
                break # Found a solution for this 'a', move to next 'a'

print("\nFound Isosceles Solutions (a=b):")
if not solutions_isosceles:
    print("No other solutions found in the numerical search range.")
else:
    max_p = 0
    for a, b, c, p in solutions_isosceles:
        print(f"Solution found: ({a:.3f}, {b:.3f}, {c:.3f}). Perimeter: {p:.3f}")
        if p > max_p:
            max_p = p
    print(f"Maximum perimeter found in search: {max_p:.3f}")

